import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { chmodSync, mkdtempSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
const root = mkdtempSync(path.join(tmpdir(), 'upgrade-probe-'));
mkdirSync(path.join(root, 'bin'));
mkdirSync(path.join(root, 'helpers'));
writeFileSync(path.join(root, 'bin/tool'), 'old-tool');
const candidate = path.join(root, 'candidate');
writeFileSync(candidate, 'new-tool');
const helper = path.join(root, 'helpers/check_sha');
writeFileSync(helper, "#!/usr/bin/env node\nconst fs=require('fs');const crypto=require('crypto');const [file,want]=process.argv.slice(2);const got=crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');process.exit(got===want?0:9);\n");
chmodSync(helper, 0o755);
const env = {...process.env, PATH: `${path.dirname(helper)}:${process.env.PATH}`};
const script = new URL('../scripts/upgrade.sh', import.meta.url).pathname;
let result = spawnSync('/bin/sh', [script, candidate, '0'.repeat(64)], {cwd:root, env});
assert.notEqual(result.status, 0);
assert.equal(readFileSync(path.join(root, 'bin/tool'), 'utf8'), 'old-tool');
const digest = createHash('sha256').update(readFileSync(candidate)).digest('hex');
result = spawnSync('/bin/sh', [script, candidate, digest], {cwd:root, env});
assert.equal(result.status, 0);
assert.equal(readFileSync(path.join(root, 'bin/tool'), 'utf8'), 'new-tool');
console.log('behavior-pass');
